import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 일용근로소득 원천징수세액 계산 값 (일 15만원 공제, 세율 6%, 산출세액의 45% 납부)
const TAX_DEDUCTION = 150000;
const TAX_RATE = 0.06;
const TAX_PAYABLE_RATIO = 0.45;
// 가정: 열람 이력의 접근 유형
const ACCESS_TYPE = 'READ';
const DOCUMENT_TYPES = ['PAYMENT_STATEMENT', 'WITHHOLDING_RECEIPT'];
const DATE_RE = /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;
const ID_RE = /^\d+$/;

function text(value: unknown): string {
  if (value === undefined || value === null) {
    return '';
  }
  return String(value).trim();
}

function requireDate(value: unknown, label: string): string {
  const v = text(value);
  if (!DATE_RE.test(v)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '을(를) YYYY-MM-DD 형식으로 입력해 주세요.');
  }
  return v;
}

function optionalDate(value: unknown, label: string): string | null {
  if (text(value) === '') {
    return null;
  }
  return requireDate(value, label);
}

function optionalId(value: unknown): string | null {
  const v = text(value);
  if (v === '') {
    return null;
  }
  if (!ID_RE.test(v)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '일용직 사원 값이 올바르지 않습니다.');
  }
  return v;
}

@Controller('api/v1')
export class FnSfr02113Controller {
  @Post('/income-certificates/generate')
  @HttpCode(200)
  async generateIncomeCertificates(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const periodStart = requireDate(data['periodStart'], '귀속 시작일');
    const periodEnd = requireDate(data['periodEnd'], '귀속 종료일');
    const dailyWorkerId = optionalId(data['dailyWorkerId']);
    return transaction(async (db) => {
      const order = await db.query(
        'SELECT CAST(:periodEnd AS date) >= CAST(:periodStart AS date) AS "ok"',
        { periodStart, periodEnd },
      );
      if (!order[0] || order[0]['ok'] !== true) {
        throw new ApiError(400, 'VALIDATION_FAILED', '귀속 종료일은 시작일보다 빠를 수 없습니다.');
      }
      const sums = await db.query(
        'SELECT p.daily_worker_id AS "dailyWorkerId", '
          + 'SUM(p.payment_amount) AS "totalPaymentAmount", '
          + 'SUM(TRUNC(GREATEST(p.payment_amount - CAST(:deduction AS numeric), 0) * CAST(:rate AS numeric) * CAST(:ratio AS numeric), 0)) AS "withheldTaxAmount" '
          + 'FROM daily_worker_payment p '
          + 'WHERE p.payment_date >= CAST(:periodStart AS date) '
          + 'AND p.payment_date <= CAST(:periodEnd AS date) '
          + 'AND (CAST(:dailyWorkerId AS bigint) IS NULL OR p.daily_worker_id = CAST(:dailyWorkerId AS bigint)) '
          + 'GROUP BY p.daily_worker_id ORDER BY p.daily_worker_id',
        {
          deduction: TAX_DEDUCTION,
          rate: TAX_RATE,
          ratio: TAX_PAYABLE_RATIO,
          periodStart,
          periodEnd,
          dailyWorkerId,
        },
      );
      if (sums.length === 0) {
        throw new ApiError(404, 'NO_PAYMENT_DATA', '해당 기간에 대상 급여가 없습니다.');
      }
      let generatedCount = 0;
      for (const row of sums) {
        for (const documentType of DOCUMENT_TYPES) {
          const params = {
            id: String(row['dailyWorkerId']),
            documentType,
            periodStart,
            periodEnd,
            total: row['totalPaymentAmount'],
            tax: row['withheldTaxAmount'],
          };
          const updated = await db.execute(
            'UPDATE income_certificate SET total_payment_amount = CAST(:total AS numeric), '
              + 'withheld_tax_amount = CAST(:tax AS numeric), issued_at = now(), updated_at = now() '
              + "WHERE daily_worker_id = CAST(:id AS bigint) AND certificate_category = 'DAILY_WAGE' "
              + 'AND document_type = :documentType '
              + 'AND period_start = CAST(:periodStart AS date) AND period_end = CAST(:periodEnd AS date)',
            params,
          );
          if (updated === 0) {
            await db.query(
              'INSERT INTO income_certificate (daily_worker_id, certificate_category, document_type, '
                + 'period_start, period_end, total_payment_amount, withheld_tax_amount, '
                + 'resident_number_enc, issued_at, created_at, updated_at) '
                + "SELECT w.daily_worker_id, 'DAILY_WAGE', CAST(:documentType AS varchar), "
                + 'CAST(:periodStart AS date), CAST(:periodEnd AS date), '
                + 'CAST(:total AS numeric), CAST(:tax AS numeric), '
                + 'w.resident_registration_no_enc, now(), now(), now() '
                + 'FROM daily_worker w WHERE w.daily_worker_id = CAST(:id AS bigint) '
                + 'RETURNING income_certificate_id AS "incomeCertificateId"',
              params,
            );
          }
          generatedCount += 1;
        }
      }
      return { generatedCount };
    });
  }

  @Get('/income-certificates')
  async listIncomeCertificates(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const q = checks.queryOf(req.query);
    const periodStart = optionalDate(q['periodStart'], '귀속 시작일');
    const periodEnd = optionalDate(q['periodEnd'], '귀속 종료일');
    const dailyWorkerId = optionalId(q['dailyWorkerId']);
    const documentTypeText = text(q['documentType']);
    if (documentTypeText !== '' && !DOCUMENT_TYPES.includes(documentTypeText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서 종류 값이 올바르지 않습니다.');
    }
    const documentType = documentTypeText === '' ? null : documentTypeText;
    const pageText = text(q['page']);
    const sizeText = text(q['size']);
    if ((pageText !== '' && !ID_RE.test(pageText)) || (sizeText !== '' && !ID_RE.test(sizeText))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기는 0 이상의 숫자여야 합니다.');
    }
    const page = pageText === '' ? 0 : Number(pageText);
    let size = sizeText === '' ? 20 : Number(sizeText);
    if (size < 1) {
      size = 20;
    }
    if (size > 200) {
      size = 200;
    }
    return transaction(async (db) => {
      await db.query(
        'INSERT INTO personal_info_access_log (employee_id, target_info_type, access_type, accessed_at, created_at, updated_at) '
          + 'VALUES (CAST(:userId AS bigint), :targetInfoType, :accessType, now(), now(), now()) '
          + 'RETURNING personal_info_access_log_id AS "personalInfoAccessLogId"',
        { userId: user.id, targetInfoType: '일용근로소득 지급명세서', accessType: ACCESS_TYPE },
      );
      const where =
        " WHERE certificate_category = 'DAILY_WAGE' "
        + 'AND (CAST(:periodStart AS date) IS NULL OR period_start >= CAST(:periodStart AS date)) '
        + 'AND (CAST(:periodEnd AS date) IS NULL OR period_end <= CAST(:periodEnd AS date)) '
        + 'AND (CAST(:dailyWorkerId AS bigint) IS NULL OR daily_worker_id = CAST(:dailyWorkerId AS bigint)) '
        + 'AND (CAST(:documentType AS varchar) IS NULL OR document_type = CAST(:documentType AS varchar))';
      const filters = { periodStart, periodEnd, dailyWorkerId, documentType };
      const items = await db.query(
        'SELECT income_certificate_id AS "incomeCertificateId", '
          + 'daily_worker_id AS "dailyWorkerId", '
          + 'document_type AS "documentType", '
          + 'period_start AS "periodStart", '
          + 'period_end AS "periodEnd", '
          + 'total_payment_amount AS "totalPaymentAmount", '
          + 'withheld_tax_amount AS "withheldTaxAmount", '
          + 'issued_at AS "issuedAt" '
          + 'FROM income_certificate'
          + where
          + ' ORDER BY income_certificate_id DESC LIMIT :size OFFSET :offset',
        { ...filters, size, offset: page * size },
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM income_certificate' + where,
        filters,
      );
      const total = counts[0] ? Number(counts[0]['total']) : 0;
      return { items, page, size, total };
    });
  }
}

