import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;
const DOCUMENT_TYPE_OPTIONS: [string, string][] = [
  ['PAYMENT_STATEMENT', '일용근로소득 지급명세서'],
  ['WITHHOLDING_RECEIPT', '일용근로소득 원천징수영수증'],
];

function documentTypeName(value: unknown): string {
  const found = DOCUMENT_TYPE_OPTIONS.find(([code]) => code === value);
  return found ? found[1] : String(value ?? '');
}

export default function FnSfr02113Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<Row>({});
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [generating, setGenerating] = useState(false);
  const [genForm, setGenForm] = useState<Row>({});

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/income-certificates', role, undefined, { ...applied, page, size: SIZE }),
    [role, JSON.stringify(applied), page],
  );

  function search() {
    setPage(0);
    setApplied({ ...draft });
  }

  function reset() {
    setDraft({});
    setPage(0);
    setApplied({});
  }

  async function generate() {
    if (!genForm['periodStart'] || !genForm['periodEnd']) {
      throw new Error('귀속 시작일과 귀속 종료일을 입력해 주세요.');
    }
    const body: Row = {
      periodStart: genForm['periodStart'],
      periodEnd: genForm['periodEnd'],
    };
    if (genForm['dailyWorkerId'] !== undefined && genForm['dailyWorkerId'] !== '') {
      body['dailyWorkerId'] = genForm['dailyWorkerId'];
    }
    const result = await call<Row>('POST', '/income-certificates/generate', role, body);
    notify(String(result['generatedCount'] ?? 0) + '건의 문서를 생성했습니다.');
    setGenerating(false);
    setGenForm({});
    reload();
  }

  if (selected) {
    return (
      <div className='doc'>
        <button className='ghost' onClick={() => setSelected(null)}>목록으로 돌아가기</button>
        <section className='box'>
          <h2>문서 정보</h2>
          <Pairs
            items={[
              ['문서 종류', documentTypeName(selected['documentType'])],
              ['일용직 사원', <RefName table='daily_worker' role={role} value={selected['dailyWorkerId']} />],
              ['귀속 시작일', <DateText value={selected['periodStart']} />],
              ['귀속 종료일', <DateText value={selected['periodEnd']} />],
            ]}
          />
        </section>
        <section className='box'>
          <h2>지급과 원천징수</h2>
          <Pairs
            items={[
              ['총지급액', <Num value={selected['totalPaymentAmount']} />],
              ['원천징수세액', <Num value={selected['withheldTaxAmount']} />],
              ['발급 일시', <DateText value={selected['issuedAt']} time />],
            ]}
          />
        </section>
      </div>
    );
  }

  return (
    <div className='doc'>
      <section className='box'>
        <h2>일용근로소득 지급명세서·원천징수영수증</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='귀속 시작일'>
            <DateInput value={draft['periodStart']} onChange={(v) => setDraft({ ...draft, periodStart: v })} />
          </Field>
          <Field label='귀속 종료일'>
            <DateInput value={draft['periodEnd']} onChange={(v) => setDraft({ ...draft, periodEnd: v })} />
          </Field>
          <Field label='일용직 사원'>
            <LookupSelect
              table='daily_worker'
              role={role}
              value={draft['dailyWorkerId']}
              onChange={(v) => setDraft({ ...draft, dailyWorkerId: v })}
            />
          </Field>
          <Field label='문서 종류'>
            <Select
              value={draft['documentType']}
              onChange={(v) => setDraft({ ...draft, documentType: v })}
              options={DOCUMENT_TYPE_OPTIONS}
            />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button onClick={() => setGenerating(true)}>명세서·영수증 생성</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          columns={[
            { key: 'dailyWorkerId', label: '일용직 사원', render: (r) => <RefName table='daily_worker' role={role} value={r['dailyWorkerId']} /> },
            { key: 'documentType', label: '문서 종류', render: (r) => <Badge value={documentTypeName(r['documentType'])} /> },
            { key: 'periodStart', label: '귀속 기간', render: (r) => <span><DateText value={r['periodStart']} /> ~ <DateText value={r['periodEnd']} /></span> },
            { key: 'totalPaymentAmount', label: '총지급액', render: (r) => <Num value={r['totalPaymentAmount']} /> },
            { key: 'withheldTaxAmount', label: '원천징수세액', render: (r) => <Num value={r['withheldTaxAmount']} /> },
          ]}
          rows={loading ? [] : data?.items ?? []}
          onRowClick={(r) => setSelected(r)}
          empty='아직 생성한 문서가 없습니다. 위의 생성 버튼으로 귀속 기간을 정해 만들어 주세요.'
        />
        <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {generating ? (
        <Drawer title='명세서·영수증 생성' onClose={() => setGenerating(false)}>
          <Form
            onSubmit={generate}
            submit='생성'
            note='기간 내 일용직 급여로 지급명세서와 원천징수영수증을 한 쌍씩 만듭니다. 같은 기간의 기존 문서는 새 값으로 갱신됩니다.'
          >
            <Field label='귀속 시작일' required>
              <DateInput value={genForm['periodStart']} onChange={(v) => setGenForm({ ...genForm, periodStart: v })} />
            </Field>
            <Field label='귀속 종료일' required>
              <DateInput value={genForm['periodEnd']} onChange={(v) => setGenForm({ ...genForm, periodEnd: v })} />
            </Field>
            <Field label='일용직 사원' hint='비우면 기간 내 급여가 있는 모든 일용직을 대상으로 합니다.'>
              <LookupSelect
                table='daily_worker'
                role={role}
                value={genForm['dailyWorkerId']}
                onChange={(v) => setGenForm({ ...genForm, dailyWorkerId: v })}
              />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
